+                        @(_isValidating ? "Validating..." : "Next")
+                    </button>
+                </div>
+            </section>
+            break;
+
+        case 1:
+            @* Step 2 — Work History *@
+            <section>
+                <h2>Work History</h2>
+                @for (int i = 0; i < _workEntries.Count; i++)
+                {
+                    var index = i;
+                    <fieldset class="work-entry">
+                        <legend>Position @(index + 1)</legend>
+                        @if (_workEntries.Count > 1)
+                        {
+                            <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
+                        }
+                        <div class="form-group">
+                            <label>Company Name *</label>
+                            <input type="text" @bind="_workEntries[index].Company" @bind:event="oninput" />
+                        </div>
+                        <div class="form-group">
+                            <label>Job Title *</label>
+                            <input type="text" @bind="_workEntries[index].Title" @bind:event="oninput" />
+                        </div>
+                        <div class="form-group">
+                            <label>Start Date *</label>
+                            <input type="date" @bind="_workEntries[index].StartDate" />
+                        </div>
+                        <div class="form-group">
+                            <label>
+                                <input type="checkbox" @bind="_workEntries[index].IsCurrent" />
+                                Currently working here
+                            </label>
+                        </div>
+                        @if (!_workEntries[index].IsCurrent)
+                        {
+                            <div class="form-group">
+                                <label>End Date</label>
+                                <input type="date" @bind="_workEntries[index].EndDate" />
+                            </div>
+                        }
+                        <div class="form-group">
+                            <label>Description *</label>
+                            <textarea rows="3" @bind="_workEntries[index].Description" @bind:event="oninput"></textarea>
+                        </div>
+                    </fieldset>
+                }
+                <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
+                <div class="form-actions">
+                    <button class="btn-back" @onclick="PreviousStep">Back</button>
+                    <button class="btn-next" @onclick="NextStep">Next</button>
+                </div>
+            </section>
+            break;
+
+        case 2:
+            @* Step 3 — References *@
+            <section>
+                <h2>References</h2>
+                @for (int i = 0; i < _references.Count; i++)
+                {
+                    var index = i;
+                    <fieldset class="reference-entry">
+                        <legend>Reference @(index + 1)</legend>
+                        @if (_references.Count > 2)
+                        {
+                            <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
+                        }
+                        <div class="form-group">
+                            <label>Name *</label>
+                            <input type="text" @bind="_references[index].Name" @bind:event="oninput" />
+                        </div>
+                        <div class="form-group">
+                            <label>Relationship *</label>
+                            <input type="text" @bind="_references[index].Relationship" @bind:event="oninput" />
+                        </div>
+                        <div class="form-group">
+                            <label>Email *</label>
+                            <input type="email" @bind="_references[index].Email" @bind:event="oninput" />
+                        </div>
+                        <div class="form-group">
+                            <label>Phone *</label>
+                            <input type="tel" @bind="_references[index].Phone" @bind:event="oninput" />
+                        </div>
+                    </fieldset>
+                }
+                @if (_references.Count < 3)
+                {
+                    <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
+                }
+                <div class="form-actions">
+                    <button class="btn-back" @onclick="PreviousStep">Back</button>
+                    <button class="btn-next" @onclick="NextStep">Next</button>
+                </div>
+            </section>
+            break;
+
+        case 3:
+            @* Step 4 — Cover Letter *@
+            <section>
+                <h2>Cover Letter</h2>
+                <div class="form-group">
+                    <label for="coverLetter">Write your cover letter *</label>
+                    <textarea id="coverLetter" rows="12" maxlength="2000"
+                              @bind="_coverLetter" @bind:event="oninput"></textarea>
+                    <span class="char-count">@_coverLetter.Length / 2000 characters</span>
+                </div>
+                <div class="form-actions">
+                    <button class="btn-back" @onclick="PreviousStep">Back</button>
+                    <button class="btn-next" @onclick="NextStep">Next</button>
+                </div>
+            </section>
+            break;
+
+        case 4:
+            @* Step 5 — Review & Submit *@
+            <section>
+                @if (_submitted)
+                {
+                    <div class="confirmation">
+                        <h2>✓ Application Submitted!</h2>
+                        <p>Your application has been received. Your application ID is:</p>
+                        <p class="application-id"><strong>@_applicationId</strong></p>
+                        <p>You will receive a confirmation email at <strong>@_email</strong>.</p>
+                    </div>
+                }
+                else
+                {
+                    <h2>Review & Submit</h2>
+
+                    <div class="review-section">
+                        <h3>Personal Information <button class="btn-edit" @onclick="() => GoToStep(0)">Edit</button></h3>
+                        <dl>
+                            <dt>Full Name</dt><dd>@_fullName</dd>
+                            <dt>Email</dt><dd>@_email</dd>
+                            <dt>Phone</dt><dd>@_phone</dd>
+                            <dt>Address</dt><dd>@_address</dd>
+                        </dl>
+                    </div>
+
+                    <div class="review-section">
+                        <h3>Work History <button class="btn-edit" @onclick="() => GoToStep(1)">Edit</button></h3>
+                        @foreach (var entry in _workEntries)
+                        {
+                            <div class="review-entry">
+                                <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
+                                <span>@entry.StartDate.ToString("MMM yyyy") – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</span><br />
+                                <p>@entry.Description</p>
+                            </div>
+                        }
+                    </div>
+
+                    <div class="review-section">
+                        <h3>References <button class="btn-edit" @onclick="() => GoToStep(2)">Edit</button></h3>
+                        @foreach (var reference in _references)
+                        {
+                            <div class="review-entry">
+                                <strong>@reference.Name</strong> (@reference.Relationship)<br />
+                                @reference.Email | @reference.Phone
+                            </div>
+                        }
+                    </div>
+
+                    <div class="review-section">
+                        <h3>Cover Letter <button class="btn-edit" @onclick="() => GoToStep(3)">Edit</button></h3>
+                        <p class="cover-letter-preview">@_coverLetter</p>
+                    </div>
+
+                    <div class="form-actions">
+                        <button class="btn-back" @onclick="PreviousStep">Back</button>
+                        <button class="btn-submit" @onclick="SubmitApplication" disabled="@_isSubmitting">
+                            @(_isSubmitting ? "Submitting..." : "Submit Application")
+                        </button>
+                    </div>
+                }
+            </section>
+            break;
+    }
+</div>
+
+@code {
+    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+
+    private int _currentStep;
+    private int _highestCompletedStep = -1;
+    private string _errorMessage = string.Empty;
+    private bool _isValidating;
+    private bool _isSubmitting;
+    private bool _submitted;
+    private int _applicationId;
+
+    // Step 1 state
+    private string _fullName = string.Empty;
+    private string _email = string.Empty;
+    private string _phone = string.Empty;
+    private string _address = string.Empty;
+
+    // Step 2 state
+    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
+
+    // Step 3 state
+    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4 state
+    private string _coverLetter = string.Empty;
+
+    private string GetStepClass(int step)
+    {
+        if (step == _currentStep) return "current";
+        if (IsStepCompleted(step)) return "completed";
+        return "future";
+    }
+
+    private bool IsStepCompleted(int step) => step <= _highestCompletedStep;
+
+    private bool IsStepAccessible(int step) => step <= _highestCompletedStep + 1;
+
+    private void GoToStep(int step)
+    {
+        if (IsStepAccessible(step))
+        {
+            _currentStep = step;
+            _errorMessage = string.Empty;
+        }
+    }
+
+    private async Task NextStep()
+    {
+        _errorMessage = string.Empty;
+
+        if (!ValidateCurrentStep())
+            return;
+
+        if (_currentStep == 0)
+        {
+            _isValidating = true;
+            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
+            _isValidating = false;
+            if (!emailValid)
+            {
+                _errorMessage = "Please enter a valid email address.";
+                return;
+            }
+        }
+
+        if (_currentStep > _highestCompletedStep)
+            _highestCompletedStep = _currentStep;
+
+        _currentStep++;
+    }
+
+    private void PreviousStep()
+    {
+        if (_currentStep > 0)
+        {
+            _currentStep--;
+            _errorMessage = string.Empty;
+        }
+    }
+
+    private bool ValidateCurrentStep()
+    {
+        switch (_currentStep)
+        {
+            case 0:
+                if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email) ||
+                    string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
+                {
+                    _errorMessage = "All fields are required.";
+                    return false;
+                }
+                break;
+            case 1:
+                foreach (var entry in _workEntries)
+                {
+                    if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
+                        entry.StartDate == default || string.IsNullOrWhiteSpace(entry.Description))
+                    {
+                        _errorMessage = "Please complete all required fields for each position.";
+                        return false;
+                    }
+                }
+                break;
+            case 2:
+                foreach (var r in _references)
+                {
+                    if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
+                        string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
+                    {
+                        _errorMessage = "Please complete all required fields for each reference.";
+                        return false;
+                    }
+                }
+                break;
+            case 3:
+                if (string.IsNullOrWhiteSpace(_coverLetter))
+                {
+                    _errorMessage = "A cover letter is required.";
+                    return false;
+                }
+                break;
+        }
+        return true;
+    }
+
+    private void AddWorkEntry() => _workEntries.Add(new WorkEntryModel());
+
+    private void RemoveWorkEntry(int index)
+    {
+        if (_workEntries.Count > 1)
+            _workEntries.RemoveAt(index);
+    }
+
+    private void AddReference()
+    {
+        if (_references.Count < 3)
+            _references.Add(new ReferenceModel());
+    }
+
+    private void RemoveReference(int index)
+    {
+        if (_references.Count > 2)
+            _references.RemoveAt(index);
+    }
+
+    private async Task SubmitApplication()
+    {
+        _isSubmitting = true;
+        _errorMessage = string.Empty;
+
+        try
+        {
+            var personal = new PersonalInfo(_fullName, _email, _phone, _address);
+            var workEntries = _workEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList();
+            var work = new WorkHistory(workEntries);
+            var references = _references.Select(r =>
+                new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+
+            var application = new JobApplication(personal, work, references, _coverLetter);
+            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
+            _submitted = true;
+            _highestCompletedStep = 4;
+        }
+        catch (Exception ex)
+        {
+            _errorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            _isSubmitting = false;
+        }
+    }
+
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = string.Empty;
+        public string Title { get; set; } = string.Empty;
+        public DateTime StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = string.Empty;
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = string.Empty;
+        public string Relationship { get; set; } = string.Empty;
+        public string Email { get; set; } = string.Empty;
+        public string Phone { get; set; } = string.Empty;
+    }
+}
