+    background: none;
+    color: #0d6efd;
+    border: 1px solid #0d6efd;
+    border-radius: 0.25rem;
+    font-size: 0.8rem;
+    cursor: pointer;
+    margin-left: 0.5rem;
+}
+
+.btn-edit:hover {
+    background: #0d6efd;
+    color: white;
+}
+
+.validation-error {
+    padding: 0.75rem 1rem;
+    background: #f8d7da;
+    color: #842029;
+    border: 1px solid #f5c2c7;
+    border-radius: 0.375rem;
+    margin-bottom: 1rem;
+}
+
+.work-entry, .reference-entry {
+    border: 1px solid #ddd;
+    border-radius: 0.5rem;
+    padding: 1rem;
+    margin-bottom: 1rem;
+}
+
+.work-entry legend, .reference-entry legend {
+    font-weight: 600;
+    padding: 0 0.5rem;
+}
+
+.char-count {
+    display: block;
+    text-align: right;
+    font-size: 0.85rem;
+    color: #666;
+    margin-top: 0.3rem;
+}
+
+.review-section {
+    border: 1px solid #eee;
+    border-radius: 0.5rem;
+    padding: 1rem;
+    margin-bottom: 1rem;
+}
+
+.review-section h3 {
+    margin-top: 0;
+    display: flex;
+    align-items: center;
+}
+
+.review-section dl {
+    display: grid;
+    grid-template-columns: auto 1fr;
+    gap: 0.3rem 1rem;
+}
+
+.review-section dt {
+    font-weight: 600;
+    color: #555;
+}
+
+.review-entry {
+    padding: 0.5rem 0;
+    border-bottom: 1px solid #f0f0f0;
+}
+
+.review-entry:last-child {
+    border-bottom: none;
+}
+
+.cover-letter-preview {
+    white-space: pre-wrap;
+    background: #f8f9fa;
+    padding: 1rem;
+    border-radius: 0.375rem;
+}
+
+.confirmation {
+    text-align: center;
+    padding: 2rem;
+}
+
+.confirmation h2 {
+    color: #198754;
+}
+
+.application-id {
+    font-size: 1.5rem;
+    color: #0d6efd;
+}
+
